function totals(rows){let B=0,E=0,L=0;rows.forEach(raw=>{const r=effective(raw);B+=Number(r.B);E+=Number(r.E);L+=Math.max(r.B-r.E,0)});return{N:rows.length,B,E,D:E-B,L,R:B===0?null:(E-B)/B*100}}
