function userRolesSave(){const u=S.users.find(v=>v.id===activeId),chosen=[...document.querySelectorAll('input[name="user-role-check"]:checked')].map(v=>v.value),business=chosen.filter(v=>v!=='系统管理'),own={'企业':'企业','市级':'市级审核','省级':'省级业务','系统管理':null}[u.type];if(business.length>1||business.some(v=>v!==own)||chosen.includes('系统管理')&&!['省级','系统管理'].includes(u.type))return errorMessages(['业务身份互斥，不能跨身份授权；管理权限仅用于省级或独立管理账号。']);u.roles=chosen;log('变更角色',u.login,chosen.join('、')||'无角色，停止业务');close();shell();toast('角色已保存；无角色账号停止业务访问')}
