function codeSave(){if(!requireRole('admin'))return;const f=firm(),type=$('#codeType').value,raw=$('#enterpriseCode').value.trim().toUpperCase(),code=type==='ORG9'?raw.replace('-',''):raw,reason=$('#code-reason').value.trim(),city=$('#codeCity').value;if(!['YN-C01','YN-C02'].includes(city)||!(type==='ORG9'?/^[A-Z0-9]{9}$/:/^[A-Z0-9]{18}$/).test(code)||!reason||charLen(reason)>500||Object.values(S.firms).some(x=>x.id!==f.id&&x.profile.enterpriseCode===code&&x.profile.codeType===type))return errorMessages(['编码须符合9/18位格式且类型加值唯一；理由1至500字。']);Object.assign(f.profile,{codeType:type,enterpriseCode:code,cityCode:city,countyCode:city+'-K01'});f.profileVersion++;f.draft=copy(f.profile);log('管理编码地区纠错',f.profile.name,reason);close();shell();toast('新资料版本已保存，企业UUID及历史快照保持不变')}
